import{_ as i,a as r,b as t,c as s,d as n,e as l,f as d}from"./chunks/WF_BGs-02.C2X8bk-5.js";import{_ as h,a as c,b as m,c as g,d as p,e as u,f,g as y,h as _,i as w,j as b}from"./chunks/sq_ad01.DxFALBiF.js";import{_ as v,a as k,b as q,c as x,d as z,e as P,f as I,g as S,h as A,i as $,j as C,k as U,l as D,m as T}from"./chunks/storyboard.D1pbC7Zm.js";import{_ as G}from"./chunks/DEER.BUn6HE6V.js";import{_ as B,a as F}from"./chunks/GG_icons.CHMpTEl1.js";import{_ as N,a as W,b as M,c as j}from"./chunks/CC_logo03.D-5PK42t.js";import{_ as V,a as Q,o as R,U as o,b as a}from"./chunks/framework.BS4h1hlk.js";const E="/assets/sq_mistyzbrush.png",sa=JSON.parse('{"title":"2D Artwork","description":"","frontmatter":{"title":"2D Artwork","meta":[{"name":"2D artwork by Rebecca Deakin"},{"content":"Colorville, Green Gardens, Solitaire Quest"}],"thumb":"/img/.png","hidden":true,"featured":false},"headers":[],"relativePath":"portfolio/2D/index.md","filePath":"portfolio/2D/index.md","lastUpdated":1791046427000}'),O={name:"portfolio/2D/index.md"};function Z(L,e,X,J,K,H){return R(),Q("div",null,e[0]||(e[0]=[o('<h1 id="wordflow" tabindex="-1">WordFlow <a class="header-anchor" href="#wordflow" aria-label="Permalink to &quot;WordFlow&quot;">​</a></h1><h3 id="software-figma-photoshop-unity" tabindex="-1">Software: Figma, Photoshop, Unity <a class="header-anchor" href="#software-figma-photoshop-unity" aria-label="Permalink to &quot;Software: Figma, Photoshop, Unity&quot;">​</a></h3><img loading="lazy" src="'+i+'"><img loading="lazy" src="'+r+'"><p>WordFlow is a relaxing word search puzzle game where players solve engaging levels and journey through a variety of beautiful new locations.</p><h3 id="main-game-ui" tabindex="-1">Main Game UI <a class="header-anchor" href="#main-game-ui" aria-label="Permalink to &quot;Main Game UI&quot;">​</a></h3><img loading="lazy" src="'+t+'"><p>Each level featured a collection of fun, themed words to discover across the game board. Unlocking new, beautiful locations gave players a rewarding sense of achievement and progress.</p><img loading="lazy" src="'+s+'"> A daily challenge mode introduced players to uplifting quotes from a new author each day, while encouraging them to maintain a daily streak for ongoing inspiration. <h3 id="wireframes" tabindex="-1">Wireframes <a class="header-anchor" href="#wireframes" aria-label="Permalink to &quot;Wireframes&quot;">​</a></h3><img loading="lazy" src="'+n+'"> Following some initial rounds of UA testing and prospective surveys, I identified opportunities to create a more marketable theme and strengthen the overall player experience. I then took ownership of the wireframing and UX design, shaping a clear gameplay loop and user flow that encouraged players to progress level by level without feeling overwhelmed. <p>I recommended removing unnecessary friction by taking players directly into their current level, while redesigning the endgame and home experience around a minimal, lightweight interface that made the next action immediately clear.</p><p>To strengthen engagement and long-term retention, I designed several progression mechanics that layered motivation throughout the experience. A rolling, never-ending quest system gave players ongoing goals and encouragement during core gameplay, while “Daily Knowledge” created an additional reason to continue playing. I also designed the Daily Challenge streak and Quote &amp; Postcard collections to introduce longer-term progression, giving players tangible goals and a stronger sense of achievement beyond individual levels.</p><h3 id="background-images" tabindex="-1">Background Images <a class="header-anchor" href="#background-images" aria-label="Permalink to &quot;Background Images&quot;">​</a></h3><p><img loading="lazy" src="'+l+'"> <img loading="lazy" src="'+d+'"></p><p>Initial user testing and prospective player surveys showed that players responded most positively to a visual style that felt realistic, yet beautiful and charming, with a subtle painterly quality.</p><p>As the game required a large variety of travel destinations, I needed a way to generate new locations at scale without sacrificing visual consistency or limiting the player’s sense of progression through a lack of content. To address this, I trained an existing AI model using a LoRA (Low-Rank Adaptation), allowing me to generate a consistent visual style across a wide range of environments and locations.</p><p>Travel destinations were then organised into thematic groups, such as “Natural Wonders of North America,” with location selection informed by user research. Particular emphasis was placed on destinations that players identified as aspirational places they would genuinely like to visit, helping to make the player’s journey feel rewarding and motivating.</p><hr><h1 id="solitaire-quest" tabindex="-1">Solitaire Quest <a class="header-anchor" href="#solitaire-quest" aria-label="Permalink to &quot;Solitaire Quest&quot;">​</a></h1><h3 id="software-photoshop-figma-z-brush-blender-unity" tabindex="-1">Software: Photoshop, Figma, Z-Brush, Blender, Unity <a class="header-anchor" href="#software-photoshop-figma-z-brush-blender-unity" aria-label="Permalink to &quot;Software: Photoshop, Figma, Z-Brush, Blender, Unity&quot;">​</a></h3><div class="flex"><img width="120" height="120" class="flex-1 pr-3" loading="lazy" src="'+h+'"><p>Solitaire Quest was a prototype mobile game, where the player guided Misty the Cat home by playing games of Solitaire. As lead artist, I was responsible for icon &amp; UI design, character design, <a href="./../3D/index.html">3D artwork</a> &amp; <a href="./../AnimationFX/index.html">animation</a></p></div><h3 id="ui" tabindex="-1">UI <a class="header-anchor" href="#ui" aria-label="Permalink to &quot;UI&quot;">​</a></h3><img loading="lazy" src="'+c+'"><img loading="lazy" src="'+m+'"><img loading="lazy" src="'+g+'"><img loading="lazy" src="'+p+'"><img loading="lazy" src="'+u+'"><img loading="lazy" src="'+f+'"><img loading="lazy" src="'+y+'"><h3 id="character-design-workflow" tabindex="-1">Character Design Workflow <a class="header-anchor" href="#character-design-workflow" aria-label="Permalink to &quot;Character Design Workflow&quot;">​</a></h3><figure><img loading="lazy" src="'+_+'"><figcaption>After meeting with our marketing experts &amp; considering our audience, we decided on the more realistic character design</figcaption></figure><figure><img loading="lazy" src="'+E+'"><figcaption>The final character design in Z-brush - [more on the 3D workflow](../3D/index)</figcaption></figure><h3 id="app-icon-options" tabindex="-1">App Icon Options <a class="header-anchor" href="#app-icon-options" aria-label="Permalink to &quot;App Icon Options&quot;">​</a></h3><img loading="lazy" src="'+w+'"><h3 id="app-store-ad" tabindex="-1">App Store Ad <a class="header-anchor" href="#app-store-ad" aria-label="Permalink to &quot;App Store Ad&quot;">​</a></h3><video loading="lazy" controls autoplay loop><source src="'+b+'" type="video/mp4"></video><hr><h1 id="colorville" tabindex="-1">Colorville <a class="header-anchor" href="#colorville" aria-label="Permalink to &quot;Colorville&quot;">​</a></h1><h3 id="software-photoshop-illustrator-spine-unity" tabindex="-1">Software: Photoshop, Illustrator, Spine, Unity <a class="header-anchor" href="#software-photoshop-illustrator-spine-unity" aria-label="Permalink to &quot;Software: Photoshop, Illustrator, Spine, Unity&quot;">​</a></h3>',42),a("div",{class:"flex"},[a("img",{class:"flex-1 pr-3",width:"120",height:"120",img:"",loading:"lazy",src:v}),a("p",null,"Colorville is a bright, colourful prototype mobile game, where the player completed color-by-number images to bring them back to life. I was responsible for isometric artwork, animation, character design & art implementation in Unity, as well as the colour-by-numbers & finished image pipeline")],-1),a("div",{class:"flex"},[a("img",{class:"flex-1 pr-3",width:"100",height:"100",img:"",loading:"lazy",src:k,style:{"vertical-align":"middle"}}),a("img",{class:"flex-1 pr-3",width:"100",height:"100",img:"",loading:"lazy",src:q,style:{"vertical-align":"middle"}}),a("img",{class:"flex-1 pr-3",width:"100",height:"100",img:"",loading:"lazy",src:x,style:{"vertical-align":"middle"}})],-1),o('<h3 id="characters" tabindex="-1">Characters <a class="header-anchor" href="#characters" aria-label="Permalink to &quot;Characters&quot;">​</a></h3><img loading="lazy" src="'+z+'"><img loading="lazy" src="'+P+'"><h3 id="isometric-buildings-props" tabindex="-1">Isometric Buildings &amp; Props <a class="header-anchor" href="#isometric-buildings-props" aria-label="Permalink to &quot;Isometric Buildings &amp; Props&quot;">​</a></h3><div class="grid grid-cols-2 gap-4"><video loading="lazy" controls autoplay loop><source src="'+I+'" type="video/mp4"></video><video loading="lazy" controls autoplay loop><source src="'+G+'" type="video/mp4"></video></div><img loading="lazy" src="'+S+'"><img loading="lazy" src="'+A+'"><img loading="lazy" src="'+$+'"><img loading="lazy" src="'+C+'"><img loading="lazy" src="'+U+'"><h3 id="merge-icons" tabindex="-1">Merge Icons <a class="header-anchor" href="#merge-icons" aria-label="Permalink to &quot;Merge Icons&quot;">​</a></h3><img loading="lazy" src="'+D+'"><h3 id="game-intro-storyboard" tabindex="-1">Game Intro Storyboard <a class="header-anchor" href="#game-intro-storyboard" aria-label="Permalink to &quot;Game Intro Storyboard&quot;">​</a></h3><img loading="lazy" src="'+T+'"><hr><h1 id="green-gardens" tabindex="-1">Green Gardens <a class="header-anchor" href="#green-gardens" aria-label="Permalink to &quot;Green Gardens&quot;">​</a></h1><h3 id="software-photoshop" tabindex="-1">Software: Photoshop <a class="header-anchor" href="#software-photoshop" aria-label="Permalink to &quot;Software: Photoshop&quot;">​</a></h3><p>Task icons and Narrative image for Green Gardens Mobile Game <img loading="lazy" src="'+B+'"><img loading="lazy" src="'+F+'"></p><hr><h1 id="crocodile-cat" tabindex="-1">Crocodile Cat <a class="header-anchor" href="#crocodile-cat" aria-label="Permalink to &quot;Crocodile Cat&quot;">​</a></h1><h3 id="software-photoshop-animation-in-unity" tabindex="-1">Software: Photoshop, Animation in Unity <a class="header-anchor" href="#software-photoshop-animation-in-unity" aria-label="Permalink to &quot;Software: Photoshop, Animation in Unity&quot;">​</a></h3><p>Crocodile Cat is a one touch action/stratagy/timing mobile game where you have to escape the jaws of a crocodile and rescue kittens with the use of your trusty jetpack and some explosive pickups. Crocodile Cat is being made with <a href="http://www.embow.co.uk/" target="_blank" rel="noreferrer">Michael Bowerman</a> in Unity.</p><img loading="lazy" src="'+N+'"><img loading="lazy" src="'+W+'"><img loading="lazy" src="'+M+'"><img loading="lazy" src="'+j+'"><hr>',27)]))}const na=V(O,[["render",Z]]);export{sa as __pageData,na as default};
